Ui.Script:
NUM_WORLDMAP_DETAIL_TILES = 12;
NUM_WORLDMAP_OVERLAYS = 0;
NUM_WORLDMAP_POIS = 0;

-- ref WorldMapFrame.lua l.509-515 is the spec. Through the PANEL MANAGER, not a bare
-- Show/Hide: the map is registered `area = "full"` (UiPanels.xml), which is what makes it
-- take the screen from the other windows on the way in and — the reason this changed —
-- what stops it opening from behind the game menu, the one window that still could
-- (director-reported, decision 0674).
function ToggleWorldMap()
    if ( WorldMapFrame:IsVisible() ) then
        HideUIPanel(WorldMapFrame);
    else
        ShowUIPanel(WorldMapFrame);
    end
end

-- Fill the screen: scale the native 1024×768 sheet up until it touches the constraining
-- screen edge — full height on any screen wider than 4:3 (the common case), full width on
-- a narrower one (ref SetupFullscreenScale, deferred at 0203, wired at 0224). The blackout
-- is a SEPARATE unscaled frame behind the sheet, so only the sheet grows.
function SetupFullscreenScale()
    local xScale = GetScreenWidth() / 1024;
    local yScale = GetScreenHeight() / 768;
    local scale = xScale;
    if ( yScale < xScale ) then
        scale = yScale;
    end
    WorldMapFrame:SetScale(scale);
end

-- One overlay tile's extent along one axis: how many pixels of art it draws, and how wide
-- the FILE holding them is. Every tile is a full 256 except the last of a row or column,
-- which carries whatever remains of the overlay — and its file is padded up to the next
-- power of two (16 the smallest the art uses), so that tile shows only the leading
-- pixels/file fraction of it. Both axes want the same answer, so they ask the same way.
local function overlayTileExtent(index, count, span)
    if ( index < count ) then
        return 256, 256;
    end
    local pixels = mod(span, 256);
    if ( pixels == 0 ) then
        pixels = 256;
    end
    local file = 16;
    while ( file < pixels ) do
        file = file * 2;
    end
    return pixels, file;
end

-- The repaint (spec: ref WorldMapFrame.lua WorldMapFrame_Update): the tile swap, the
-- discovery-overlay pool, and the zoom-out arming (POI landmarks are still deferred). The
-- "World" fallback is the reference's own hack for the nil GetMapInfo at the world level,
-- kept because our host answers nil at that level for the same reason.
function WorldMapFrame_Update()
    local mapFileName = GetMapInfo();
    if ( not mapFileName ) then
        mapFileName = "World";
    end
    for i=1, NUM_WORLDMAP_DETAIL_TILES, 1 do
        getglobal("WorldMapDetailTile"..i):SetTexture("Interface\\WorldMap\\"..mapFileName.."\\"..mapFileName..i);
    end

    -- The discovery overlays (spec: ref WorldMapFrame.lua, "Setup the overlays"): the base
    -- tiles are the unexplored parchment, and each REVEALED sub-area (GetNumMapOverlays /
    -- GetMapOverlayInfo, filtered host-side by the explored bitset) paints its detailed
    -- art over them. That art is cut into a grid of 256-px tiles, numbered 1..n across
    -- then down, which we lay onto ARTWORK textures pooled on WorldMapDetailFrame — the
    -- pool grows on demand, never shrinks, and the tail left over from a busier map is
    -- parked hidden below. Offsets are native pixels: the map renders at its native
    -- 1024×768 (no WORLDMAP_SX/SY scale, unlike the parked windowed layout), so the
    -- overlays share the detail tiles' coordinate space untouched.
    local used = 0;
    for overlay = 1, GetNumMapOverlays() do
        local art, artWidth, artHeight, originX, originY = GetMapOverlayInfo(overlay);
        local columns = ceil(artWidth/256);
        local rows = ceil(artHeight/256);
        local wanted = used + (columns * rows);
        if ( wanted > NUM_WORLDMAP_OVERLAYS ) then
            for slot = NUM_WORLDMAP_OVERLAYS + 1, wanted do
                WorldMapDetailFrame:CreateTexture("WorldMapOverlay"..slot, "ARTWORK");
            end
            NUM_WORLDMAP_OVERLAYS = wanted;
        end
        -- Tile n of the overlay is file <art>n, and its place in the grid follows from n.
        for tile = 1, columns * rows do
            local column = mod(tile - 1, columns) + 1;
            local row = ceil(tile / columns);
            local wide, fileWide = overlayTileExtent(column, columns, artWidth);
            local tall, fileTall = overlayTileExtent(row, rows, artHeight);
            used = used + 1;
            local texture = getglobal("WorldMapOverlay"..used);
            texture:SetWidth(wide);
            texture:SetHeight(tall);
            texture:SetTexCoord(0, wide/fileWide, 0, tall/fileTall);
            texture:ClearAllPoints();
            texture:SetPoint("TOPLEFT", originX + (256 * (column - 1)), -(originY + (256 * (row - 1))));
            texture:SetTexture(art..tile);
            texture:Show();
        end
    end
    for slot = used + 1, NUM_WORLDMAP_OVERLAYS do
        getglobal("WorldMapOverlay"..slot):Hide();
    end

    -- The POI icons (spec: ref WorldMapFrame.lua's landmark pass). One frame per landmark
    -- the host reports for the displayed map, grown on demand from WorldMapPOITemplate and
    -- never shrunk — the tail from a busier map is parked hidden, like the overlay pool
    -- above. The host reports the AreaPOI.dbc rows the displayed level admits (town and
    -- city icons, a capital's "Under Attack" marker, the Eastern Plaguelands towers),
    -- then the guard-directions marker (SMSG_GOSSIP_POI) last.
    local numPOIs = GetNumMapLandmarks();
    if ( numPOIs > NUM_WORLDMAP_POIS ) then
        for slot = NUM_WORLDMAP_POIS + 1, numPOIs do
            CreateFrame("Button", "WorldMapFramePOI"..slot, WorldMapButton, "WorldMapPOITemplate");
        end
        NUM_WORLDMAP_POIS = numPOIs;
    end
    for slot = 1, NUM_WORLDMAP_POIS do
        local poi = getglobal("WorldMapFramePOI"..slot);
        if ( slot > numPOIs ) then
            poi:Hide();
        else
            local name, description, textureIndex, x, y = GetMapLandmarkInfo(slot);
            WorldMapPOI_SetTexture(poi, textureIndex);
            poi.name = name;
            poi.description = description;
            poi:ClearAllPoints();
            poi:SetPoint("CENTER", "WorldMapDetailFrame", "TOPLEFT",
                x * WorldMapDetailFrame:GetWidth(), -y * WorldMapDetailFrame:GetHeight());
            poi:Show();
        end
    end

    if ( GetCurrentMapContinent() == 0 ) then
        WorldMapZoomOutButton:Disable();
    else
        WorldMapZoomOutButton:Enable();
    end
end

-- Point a POI frame's texture at its cell of Interface\Minimap\POIIcons — an 8x8 grid of
-- icons indexed across then down, the same atlas and the same indexing the minimap's
-- landmark blips use (the corpse marker below hardcodes its own cell of it).
function WorldMapPOI_SetTexture(poi, textureIndex)
    local column = mod(textureIndex, 8);
    local row = floor(textureIndex / 8);
    getglobal(poi:GetName().."Texture"):SetTexCoord(
        column * 0.125, (column + 1) * 0.125, row * 0.125, (row + 1) * 0.125);
end

-- Every marker on the sheet — the corpse, a POI — names itself in the shared GameTooltip,
-- and every one of them wants the plate opening AWAY from the edge it sits nearest, so the
-- side pick lives here once instead of in each OnEnter. `subtitle` is the second line the
-- landmarks that carry a live status use; the rest pass nothing.
-- The party blips (ref WorldMapFrame.lua:391-403's party arm, report B320): the same
-- (0,0)-means-hide law as the player and the corpse, one frame per slot.
--
-- It rides the per-frame pass beside those two rather than WorldMapFrame_Update, where the
-- reference keeps it: a member's position moves continuously and the map has no event that
-- fires when it does, so placing it on the repaint alone would freeze every blip between
-- roster changes. Its own function so the live pass and the tests enter it identically.
--
-- The reference's RAID arm is not taken — see the blip frames' note.
function WorldMapParty_Update()
    for i = 1, 4 do
        local blip = getglobal("WorldMapParty" .. i)
        local px, py = GetPlayerMapPosition("party" .. i)
        if ( px == 0 and py == 0 ) then
            blip:Hide()
        else
            px = px * WorldMapDetailFrame:GetWidth()
            py = -py * WorldMapDetailFrame:GetHeight()
            blip:SetPoint("CENTER", "WorldMapDetailFrame", "TOPLEFT", px, py)
            blip:Show()
        end
    end
end

-- A party blip's hover names the member (ref WorldMapUnit_OnEnter, which reads the
-- frame's own `unit`). The frame id IS the party slot, so the token needs no bookkeeping.
function WorldMapParty_OnEnter(blip)
    local unit = "party" .. blip:GetID()
    WorldMapMarker_ShowTooltip(blip, UnitName(unit) or UNKNOWN)
end

function WorldMapMarker_ShowTooltip(marker, title, subtitle)
    local markerX = marker:GetCenter();
    local sheetX = marker:GetParent():GetCenter();
    if ( markerX > sheetX ) then
        GameTooltip:SetOwner(marker, "ANCHOR_LEFT");
    else
        GameTooltip:SetOwner(marker, "ANCHOR_RIGHT");
    end
    GameTooltip:SetText(title);
    if ( subtitle and subtitle ~= "" ) then
        GameTooltip:AddLine(subtitle, 1, 1, 1);
    end
    GameTooltip:Show();
end

-- The reference's rule: zone view → its continent; continent view → the world.
function WorldMapZoomOutButton_OnClick()
    if ( GetCurrentMapZone() ~= 0 ) then
        SetMapZoom(GetCurrentMapContinent());
    else
        SetMapZoom(0);
    end
end

-- ── The continent/zone dropdowns (the reference's wiring; its `arg.n` vararg walk is
-- written here as select("#", ...), the 5.1-native spelling and this tree's house style
-- for it). ────────────────────────────────────────────────────────────────────────────
function WorldMapContinentsDropDown_OnLoad()
    UIDropDownMenu_Initialize(this, WorldMapContinentsDropDown_Initialize);
    UIDropDownMenu_SetWidth(130);
end

function WorldMapContinentsDropDown_Initialize()
    WorldMapFrame_LoadContinents(GetMapContinents());
end

function WorldMapFrame_LoadContinents(...)
    local info;
    for i=1, select("#", ...), 1 do
        info = {};
        info.text = select(i, ...);
        info.func = WorldMapContinentButton_OnClick;
        UIDropDownMenu_AddButton(info);
    end
end

function WorldMapZoneDropDown_OnLoad()
    UIDropDownMenu_Initialize(this, WorldMapZoneDropDown_Initialize);
    UIDropDownMenu_SetWidth(130);
end

function WorldMapZoneDropDown_Initialize()
    WorldMapFrame_LoadZones(GetMapZones(GetCurrentMapContinent()));
end

function WorldMapFrame_LoadZones(...)
    local info;
    for i=1, select("#", ...), 1 do
        info = {};
        info.text = select(i, ...);
        info.func = WorldMapZoneButton_OnClick;
        UIDropDownMenu_AddButton(info);
    end
end

function WorldMapContinentButton_OnClick()
    UIDropDownMenu_SetSelectedID(WorldMapContinentDropDown, this:GetID());
    SetMapZoom(this:GetID());
end

function WorldMapZoneButton_OnClick()
    UIDropDownMenu_SetSelectedID(WorldMapZoneDropDown, this:GetID());
    SetMapZoom(GetCurrentMapContinent(), this:GetID());
end

function WorldMap_UpdateZoneDropDownText()
    if ( GetCurrentMapZone() == 0 ) then
        UIDropDownMenu_ClearAll(WorldMapZoneDropDown);
    else
        UIDropDownMenu_SetSelectedID(WorldMapZoneDropDown, GetCurrentMapZone());
    end
end

function WorldMap_UpdateContinentDropDownText()
    if ( GetCurrentMapContinent() == 0 ) then
        UIDropDownMenu_ClearAll(WorldMapContinentDropDown);
    else
        UIDropDownMenu_SetSelectedID(WorldMapContinentDropDown, GetCurrentMapContinent());
    end
end

-- Where the cursor sits inside a map-sized frame, as a fraction of it measured from the
-- TOPLEFT: (0,0) the top-left corner of the map art, (1,1) the bottom-right. Both sides of
-- the host's map API — the click (ProcessMapClick) and the hover (UpdateMapHighlight) —
-- take a position in exactly that space, and the cursor arrives in screen pixels with the
-- y axis pointing the other way, so this is the one conversion between them: undo the
-- frame's effective scale, then measure from its edges, which a frame gives up as its
-- center and its size (each edge being half the size away from the center).
local function cursorMapPosition(frame)
    local cursorX, cursorY = GetCursorPosition();
    local scale = frame:GetEffectiveScale();
    local midX, midY = frame:GetCenter();
    local frameWidth = frame:GetWidth();
    local frameHeight = frame:GetHeight();
    local fromLeft = (cursorX / scale) - (midX - (frameWidth/2));
    local fromTop = (midY + (frameHeight/2)) - (cursorY / scale);
    return fromLeft / frameWidth, fromTop / frameHeight;
end

-- Left click drills into whatever the host finds at that map position; every other button
-- is the zoom-out shortcut (ref WorldMapButton_OnClick — ours takes no button argument,
-- since nothing but the map button itself routes here).
function WorldMapButton_OnClick(mouseButton)
    CloseDropDownMenus();
    if ( mouseButton == "LeftButton" ) then
        ProcessMapClick(cursorMapPosition(WorldMapButton));
    else
        WorldMapZoomOutButton_OnClick();
    end
end

-- The per-frame hover pass (spec: ref WorldMapButton_OnUpdate), reduced to the area
-- highlight + the player blip (raid/flags/ping are still deferred; the party blips
-- landed with B320 and ride WorldMapFrame_Update, not this pass).
-- UpdateMapHighlight is a stub until the area-bitmap source lands (wow-re dispatch) — a
-- nil area/art takes the hide paths.
function WorldMapButton_OnUpdate(elapsed)
    local width = this:GetWidth();
    local height = this:GetHeight();
    local area, art, cropX, cropY, sizeX, sizeY, atX, atY =
        UpdateMapHighlight(cursorMapPosition(this));
    WorldMapFrameAreaLabel:SetText(area or "");
    if ( art ) then
        -- The sub-area under the cursor lights up: <zone>Highlight holds one shape per
        -- sub-area, of which crop names the fraction actually used (the file is padded to
        -- a power of two), while size and at are the shape's extent and top-left corner as
        -- fractions of the map — so both scale by the button's pixel size. Nothing to draw
        -- for a degenerate shape, but the art is still swapped in for the next frame.
        WorldMapHighlight:SetTexCoord(0, cropX, 0, cropY);
        WorldMapHighlight:SetTexture("Interface\\WorldMap\\"..art.."\\"..art.."Highlight");
        local drawWidth = sizeX * width;
        local drawHeight = sizeY * height;
        if ( drawWidth > 0 and drawHeight > 0 ) then
            WorldMapHighlight:SetWidth(drawWidth);
            WorldMapHighlight:SetHeight(drawHeight);
            WorldMapHighlight:SetPoint("TOPLEFT", "WorldMapDetailFrame", "TOPLEFT", atX * width, -atY * height);
            WorldMapHighlight:Show();
        end
    else
        WorldMapHighlight:Hide();
    end
    -- The player blip: the reference's engine arrow, as our rotating texture stand-in.
    WorldMapPlayerIcon:SetRotation(GetPlayerFacing());
    local playerX, playerY = GetPlayerMapPosition("player");
    if ( playerX == 0 and playerY == 0 ) then
        WorldMapPlayer:Hide();
    else
        playerX = playerX * WorldMapDetailFrame:GetWidth();
        playerY = -playerY * WorldMapDetailFrame:GetHeight();
        WorldMapPlayer:SetPoint("CENTER", "WorldMapDetailFrame", "TOPLEFT", playerX, playerY);
        WorldMapPlayer:Show();
    end
    WorldMapParty_Update()
    -- Position corpse (ref WorldMapFrame.lua:443-452 — the law is that (0,0) means hide).
    local corpseX, corpseY = GetCorpseMapPosition();
    if ( corpseX == 0 and corpseY == 0 ) then
        WorldMapCorpse:Hide();
    else
        corpseX = corpseX * WorldMapDetailFrame:GetWidth();
        corpseY = -corpseY * WorldMapDetailFrame:GetHeight();
        WorldMapCorpse:SetPoint("CENTER", "WorldMapDetailFrame", "TOPLEFT", corpseX, corpseY);
        WorldMapCorpse:Show();
    end
end

Scripts.OnEvent:
if ( this:IsVisible() ) then
    WorldMapContinentsDropDown_OnLoad();
    WorldMap_UpdateContinentDropDownText();
    WorldMapZoneDropDown_OnLoad();
    WorldMap_UpdateZoneDropDownText();
end

Scripts.OnLoad:
this:RegisterEvent("WORLD_MAP_UPDATE");
-- The hover area label inherits WorldMapTextFont (nominal 102). 33 was the
-- director's taste call (0235) — which the one-to-one raster cap (the fold-back
-- record; wow-re fontstring-overflow.md) now clamps to the byte law's 32, one
-- unit under that call and closer to it than the 36 the atlas snap used to
-- deliver. The real client draws this SetFont(33) at 32 too. Still a taste dial:
-- any value ≤ 32 is honored exactly.
WorldMapFrameAreaLabel:SetFont("Fonts\\FRIZQT__.TTF", 33);
WorldMapFrame_Update();

Scripts.OnShow:
WorldMapBlackout:Show();
SetupFullscreenScale();
SetMapToCurrentZone();
WorldMapFrame_Update();
if UpdateMicroButtons then UpdateMicroButtons() end;
PlaySound("igQuestLogOpen");
CloseDropDownMenus();

Scripts.OnHide:
WorldMapBlackout:Hide();
if UpdateMicroButtons then UpdateMicroButtons() end;
PlaySound("igQuestLogClose");
